/// url = 'https://icr.healthcampaigns.org/StructureMap/DHIS2IndicatorToICR'
/// name = 'DHIS2IndicatorToICR'
/// title = 'DHIS2 indicator, data element or reporting rate to Measure'
/// status = 'draft'

// Run by `fhir-pipes dhis2 measures --maps`, and by `fhir-pipes import run`
// over the records `dhis2 extract measures` writes.
//
// A percent (factor 100) is scored proportion, another factor ratio, and a
// plain number (denominator 1) cohort.
//
// Ids and urls are joined with `append` from source variables. FHIRPath is
// kept where it reads more clearly than the alternative: there are few
// indicators, so its cost does not matter here.

uses "https://healthcampaigns.org/fhir/dhis2/StructureDefinition/DHIS2Indicator" alias DHIS2Indicator as source
uses "http://hl7.org/fhir/StructureDefinition/Measure" alias Measure as target

group Indicator(source src : DHIS2Indicator, target m : Measure) {
  src.instance as i, src.key as k -> m.id = append(i, '-', k) "id";
  src.instance as i -> m.meta as meta, meta.tag as tag, tag.system = 'https://icr.healthcampaigns.org/CodeSystem/icr-project-tag-cs', tag.code = i "tag";
  // How DHIS2 computes the value.
  src -> m.extension as ext, ext.url = 'https://icr.healthcampaigns.org/StructureDefinition/dhis2-indicator' then {
    src.factor as v -> ext.extension as sub, sub.url = 'factor', sub.value = v "factor";
    src.typeName as v -> ext.extension as sub, sub.url = 'indicatorType', sub.value = v "indicatorType";
    src.annualized as v -> ext.extension as sub, sub.url = 'annualized', sub.value = v "annualized";
    src.decimals as v -> ext.extension as sub, sub.url = 'decimals', sub.value = v "decimals";
  } "computation";
  src.instance as i, src.key as k -> m.url = append('https://icr.healthcampaigns.org/Measure/', i, '-', k) "url";
  // The identifier system is named after what the item is: indicator, data-element or data-set.
  src.uid as uid -> m.identifier as ident, ident.use = 'official', ident.system = evaluate(src, 'https://icr.healthcampaigns.org/identifiers/dhis2/' + instance + '/' + iif(kind = 'reporting-rate', 'data-set', kind)), ident.value = uid "uid";
  src.code as code -> m.identifier as ident, ident.system = evaluate(src, 'https://icr.healthcampaigns.org/identifiers/dhis2/' + instance + '/' + iif(kind = 'reporting-rate', 'data-set', kind) + '-code'), ident.value = code "code";
  src.name as v -> m.title = v "title";
  src -> m.status = 'active' "status";
  src.date as v -> m.date = v "date";
  src.publisher as v -> m.publisher = v "publisher";
  src.description as v -> m.description = v "description";
  src.group as g -> m then Topics(src, g, m) "topics";
  src -> m.subject = create('CodeableConcept') as cc, cc.coding as c, c.system = 'http://hl7.org/fhir/resource-types', c.code = 'Location' "subject";
  src where denominator.trim() = '1' -> m.scoring as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-scoring', c.code = 'cohort', c.display = 'Cohort' "cohort";
  src where denominator.trim() != '1' and factor = 100 -> m.scoring as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-scoring', c.code = 'proportion', c.display = 'Proportion' "proportion";
  src where denominator.trim() != '1' and factor != 100 -> m.scoring as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-scoring', c.code = 'ratio', c.display = 'Ratio' "ratio";
  src -> m.group as g then {
    src where denominator.trim() = '1' -> g.population as p then {
      src -> p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'initial-population', c.display = 'Initial Population' "initialCode";
      src.numeratorDescription as d -> p.description = d "initialDescription";
      src.numerator as e -> p.criteria as cr, cr.language = 'text/x-dhis2-expression', cr.expression = e "initialExpression";
    } "initialPopulation";
    src where denominator.trim() != '1' -> g.population as p then {
      src -> p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'numerator', c.display = 'Numerator' "numeratorCode";
      src.numeratorDescription as d -> p.description = d "numeratorDescription";
      src.numerator as e -> p.criteria as cr, cr.language = 'text/x-dhis2-expression', cr.expression = e "numeratorExpression";
    } "numerator";
    src where denominator.trim() != '1' -> g.population as p then {
      src -> p.code as cc, cc.coding as c, c.system = 'http://terminology.hl7.org/CodeSystem/measure-population', c.code = 'denominator', c.display = 'Denominator' "denominatorCode";
      src.denominatorDescription as d -> p.description = d "denominatorDescription";
      src.denominator as e -> p.criteria as cr, cr.language = 'text/x-dhis2-expression', cr.expression = e "denominatorExpression";
    } "denominator";
  } "populations";
}

// One topic per group, coded so a reader can regroup items as DHIS2 does. A
// data element group in group sets gives one topic per set.
group Topics(source src : DHIS2Indicator, source g, target m : Measure) {
  g.set as s where %src.kind = 'data-element' -> m.topic as t then {
    g.uid as uid, g.name as n, src.instance as i -> t.coding as c, c.system = append('https://icr.healthcampaigns.org/CodeSystem/dhis2/', i, '/data-element-group-set/', s), c.code = uid, c.display = n "setCoding";
    g.name as n -> t.text = n "setText";
  } "inSet";
  g where %src.kind != 'data-element' or set.empty() -> m.topic as t then {
    g.uid as uid, g.name as n -> t.coding as c, c.system = evaluate(src, 'https://icr.healthcampaigns.org/CodeSystem/dhis2/' + instance + '/' + iif(kind = 'data-element', 'data-element-group', 'indicator-group')), c.code = uid, c.display = n "groupCoding";
    g.name as n -> t.text = n "groupText";
  } "inGroup";
}
